import java.io.*;
import java.util.*;

public class TaskD {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    return "-1";
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        void close() throws IOException {
            br.close();
        }
    }

    static long largestEven(long v) {
        return v - v % 2;
    }

    static long compute(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        if (a > 3) {
            return largestEven(a * b);
        }
        long s = b - b % 6;
        long o = b % 6;
        long h = 0;
        if (a == 1) {
            if (o == 4) h = 2;
            else if (o == 5) h = 4;
        } else if (a == 2) {
            if (o == 3) h = 4;
            else if (o == 4) h = 8;
            else if (o == 5) h = 10;
        } else if (a == 3) {
            if (o == 2) h = 4;
            else if (o == 3) h = 8;
            else if (o == 4) h = 12;
            else if (o == 5) h = 14;
        }
        if (a + b > 9 && a > 1) {
            return largestEven(a * b);
        }
        return s * a + h;
    }

    public static void main(String[] args) throws IOException {
        InputStream input = System.in;
        PrintStream output = System.out;
        try {
            File f = new File("a.in");
            if (f.exists() && f.canRead()) {
                input = new FileInputStream(f);
                output = new PrintStream("a.out");
            }
        } catch (Throwable e) {
        }
        FastScanner fs = new FastScanner(input);
        PrintWriter out = new PrintWriter(output);
        long n = fs.nextLong();
        long m = fs.nextLong();
        out.print(compute(n, m));
        fs.close();
        out.close();
    }
}
